  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and opened tests of fundamental physics at unprecedented sensitivity. The achievement is both foundational and broadly enabling.",
        "attribution": "Katori's lattice-clock concept and Ye's complementary experimental advances are central, with credit well suited to these two.",
        "maturity": "The precision and reproducibility have advanced over decades, with clear demonstrations across laboratories and sustained scientific use.",
        "uncertainties": [
          "The relative weight of the original concept and subsequent clock implementations is difficult to divide precisely."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Alfred Y. Cho",
        "Federico Capasso",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum cascade laser established a new kind of semiconductor laser based on intersubband transitions, with major consequences for spectroscopy and mid-infrared and terahertz sources.",
        "attribution": "Cho's enabling semiconductor growth, Capasso's device concept and leadership, and Faist's central role in the first realization make a strong trio.",
        "maturity": "The principle has been confirmed across generations of devices and has supported a large, durable body of research and applications.",
        "uncertainties": [
          "The invention depended on a wider team and prior advances in semiconductor heterostructures, complicating the boundary of credit."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals made control of light through periodic optical structures a major field, including the prospect of photonic band gaps and engineered light propagation.",
        "attribution": "Yablonovitch and John independently articulated key photonic band-gap ideas; Joannopoulos made major theoretical contributions that helped establish the field.",
        "maturity": "The concepts are experimentally robust and underpin extensive work in photonics, though the broadest proposed applications have developed unevenly.",
        "uncertainties": [
          "The field grew through parallel proposals and many later contributions, making a three-person attribution necessarily selective."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics brought cavity quantum optics into an electrical circuit platform and became a foundation for controlling and measuring superconducting quantum systems.",
        "attribution": "Blais supplied key theory, while Wallraff and Schoelkopf were central to establishing and developing the experimental platform.",
        "maturity": "The core effects and control methods have been repeatedly demonstrated and adopted widely. The distinction from other superconducting-circuit advances recognized recently requires care.",
        "uncertainties": [
          "The development involved a broad international community, and the precise boundary between cQED and neighboring circuit breakthroughs is not sharp.",
          "My close research proximity to this field makes my comparative judgment less independent."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B048",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can in principle be protected against noise, turning a central obstacle into a structured physical and computational problem.",
        "attribution": "Shor and Steane developed landmark codes, while Kitaev's topological approach added a distinct and influential framework.",
        "maturity": "The theory is firmly established and experimental demonstrations have progressed substantially, though scalable fault-tolerant computation remains unachieved.",
        "uncertainties": [
          "It remains open how much Nobel recognition should wait for a convincing scalable realization rather than the foundational theory and early demonstrations."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B007",
      "proposed_laureates": [
        "David D. Awschalom",
        "Fedor Jelezko",
        "Jörg Wrachtrup"
      ],
      "assessment": {
        "nobel_worthiness": "Colour-centre spins made individual solid-state defects into controllable quantum systems, connecting spin physics, quantum optics, sensing and information processing.",
        "attribution": "Awschalom, Jelezko and Wrachtrup each made major contributions to establishing and controlling defect-spin systems; the credit set also reflects the field's distributed origins.",
        "maturity": "Single-defect control and sensing are robust, while some larger-scale quantum-network and computing goals remain in development.",
        "uncertainties": [
          "Mikhail D. Lukin's contribution is also highly consequential, and the four-name credit set exceeds the usual laureate limit."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B041",
      "proposed_laureates": [
        "Daniel Loss",
        "Lieven M. K. Vandersypen",
        "Seigo Tarucha"
      ],
      "assessment": {
        "nobel_worthiness": "Semiconductor quantum-dot spin qubits linked mesoscopic spin physics to a scalable quantum-information platform and led to sustained experimental progress.",
        "attribution": "Loss's proposal is foundational; Vandersypen and Tarucha were among the central experimental pioneers who established coherent control in quantum dots.",
        "maturity": "Coherent control and increasingly sophisticated devices are well demonstrated, but the route to large, fault-tolerant systems is still incomplete.",
        "uncertainties": [
          "The proposal-to-realization history involves several independent groups, and Daniel Loss's role may fit more naturally with the broader spin-qubit proposal story."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B042",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Programmable Rydberg arrays have created a flexible platform for quantum simulation and controlled many-body experiments, with clear potential for new regimes of quantum physics.",
        "attribution": "Browaeys and Lukin represent major experimental efforts that established programmable arrays; the broader development also includes substantial contributions from other groups.",
        "maturity": "The platform is rapidly advancing and has produced important demonstrations, but its long-term scientific reach and durability are not yet settled.",
        "uncertainties": [
          "The field remains young, and the credit set omits other major contributors, including Mark Saffman."
        ]
      }
    }
  ]
}
